-- Step AR-1: the "Single Flush Casement with Fanlight" drawing template.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
--
-- Nathan (12 Oct 2026): this is the layout sold most — ONE casement with a
-- fanlight over it, the fanlight a top-hung opener or a fixed casement sash.
--
-- The tree below was GENERATED by the board's own code, so the template is
-- exactly what the board would build: buildCasementFrame at 1200 x 1300,
-- then the mullion/transom picker at 1 column x 2 rows, then the operation
-- button setting A1 to Top Hung. A1 is the fanlight (top row, 356 high —
-- Integrate's own template value) and A2 the left-hand-hung casement below
-- it. Transom: thickness 27 with 20/20 stops and offset 356, which is the
-- height of the opening ABOVE it, exactly as Integrate stores it
-- (docs/integrate-L31115-fanlights.txt).
--
-- Product and Quantity are both is_required (Step AQ), so the product code
-- is looked up BY LABEL — the `product` reference list came from Integrate
-- and its codes are not in the repository — and the script fails loudly
-- rather than writing a code that would look set and still fail the check.
-- No stored ironmongery list: the default rules price it and follow the
-- openings (difference 4 in docs/integrate-differences.md).

BEGIN;

DO $$
DECLARE
  _profile_id    bigint;
  _casement_code text;
  _tree          jsonb := '{"key":"drawingItem_1","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1},"children":[{"key":"paintAndIronmongery_2","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_3","part_type":"notesPart","values":{},"children":[]},{"key":"price_4","part_type":"pricePart","values":{},"children":[]},{"key":"assemblyFrame_5","part_type":"assemblyFramePart","values":{"width":1200,"height":1300,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"transom_6","part_type":"transomPart","values":{"offset":356,"thicknessInFrame":27,"transomStopSize":20},"children":[]},{"key":"casementSash_7","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_8","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_9","part_type":"casementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_10","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_11","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}'::jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'casement' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''casement'' — the casement profile must exist first';
  END IF;

  SELECT code INTO _casement_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'casement' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _casement_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Casement'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  _tree := jsonb_set(_tree, '{values,product}', to_jsonb(_casement_code), true);

  IF NOT EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = 'Single Flush Casement with Fanlight') THEN
    INSERT INTO public.drawing_templates
      (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
    VALUES ('Single Flush Casement with Fanlight', 'casement', 'Casement', 'Casement',
            _profile_id, _tree, 15, TRUE);
    RAISE NOTICE 'Step AR-1: fanlight template created';
  ELSE
    UPDATE public.drawing_templates
    SET tree = _tree, default_profile_id = _profile_id, updated_at = now()
    WHERE name = 'Single Flush Casement with Fanlight';
    RAISE NOTICE 'Step AR-1: fanlight template updated in place';
  END IF;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. The four casement templates, with the fanlight one between Single and
--    Double (sort 10 / 15 / 20 / 30), each with Product and Quantity set.
SELECT name, group_name, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity
FROM   public.drawing_templates
WHERE  family = 'casement'
ORDER  BY sort_order;

-- 2. The fanlight template's shape: expect one transom (offset 356,
--    thickness 27), two casement sashes (top_hung then left_hand_hung) and
--    one cill.
SELECT t.name,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.offset') v)    AS divider_offsets,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.operation') v) AS operations,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")')) AS transoms,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "casementSashPart")')) AS sashes,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "cillPart")')) AS cills
FROM   public.drawing_templates t
WHERE  t.name = 'Single Flush Casement with Fanlight';


